-- SafetyTraining v20.053b
-- Reconcile live rope-access family: two 32h directions, 8h updates, supervisor 8h + 4h update.
-- Shared base Learning Units are reused between direction A and B.

DO $do$
DECLARE r jsonb; c jsonb; v_lu uuid; v_luv uuid; v_course uuid; v_cv uuid; v_module uuid; v_practical boolean; v_content jsonb;
BEGIN
  FOR r IN SELECT value FROM jsonb_array_elements($units$
  [
    {"k":"rope:base:risk","t":"Normativa, valutazione del rischio e scelta del sistema","s":"Comprendere quando l’accesso su fune è appropriato e quali condizioni devono essere definite prima del lavoro.","m":240,"p":false,"f":["art.116","lavori in quota","valutazione rischio","scelta accesso","piano di lavoro","organizzazione","emergenza"],"case":"Un’attività originariamente prevista con altro accesso viene spostata su albero: stabilire condizioni e pianificazione prima dell’uso delle funi."},
    {"k":"rope:base:equipment","t":"DPI, funi, connettori, discensori, bloccanti e compatibilità","s":"Riconoscere componenti del sistema, controlli, compatibilità e criteri di ritiro.","m":240,"p":true,"f":["imbracature","caschi","funi","cordini","connettori","discensori","bloccanti","carrucole","marcature","manutenzione"],"case":"Tra i dispositivi disponibili alcuni appartengono a sistemi diversi: costruire solo configurazioni previste e spiegare cosa va escluso."},
    {"k":"rope:base:anchors-rescue","t":"Ancoraggi, principi di organizzazione delle funi e soccorso","s":"Comprendere ridondanza, ancoraggi, protezione delle funi e necessità di soccorso pianificato.","m":240,"p":true,"f":["ancoraggi","doppia fune","protezione spigoli","carichi","comunicazione","piano di soccorso","sindrome da sospensione"],"case":"Una linea presenta sfregamento su ramo/corteccia e geometria instabile: individuare riposizionamento e protezioni."},
    {"k":"rope:A:setup","t":"Installazione del sistema su siti naturali/artificiali","s":"Predisporre linee, ancoraggi e protezioni per accesso dall’alto o dal basso secondo scenario.","m":240,"p":true,"f":["scelta ancoraggi","linea lavoro","linea sicurezza","accesso","protezione spigoli","area sottostante"],"case":"Predisporre un sistema didattico su struttura con cambio di direzione e bordo, motivando ogni ancoraggio."},
    {"k":"rope:A:progression","t":"Salita, discesa, frazionamenti e cambi di linea","s":"Eseguire progressione autonoma mantenendo corretta gestione delle due funi e dei dispositivi.","m":240,"p":true,"f":["salita","discesa","frazionamento","deviazione","cambio linea","passaggio ostacoli"],"case":"Percorso con frazionamento e deviazione: il corsista verbalizza protezione e sequenza prima di muoversi."},
    {"k":"rope:A:positioning","t":"Posizionamento, lavoro in sospensione e gestione attrezzi","s":"Mantenere posizione stabile e organizzare attrezzi/materiali senza compromettere funi o persone sottostanti.","m":240,"p":true,"f":["posizionamento","sospensione","comfort","attrezzi","caduta oggetti","comunicazione"],"case":"Simulare manutenzione in sospensione con attrezzi vincolati e zona inferiore segregata."},
    {"k":"rope:A:complex","t":"Deviazioni, risalite e manovre in configurazioni complesse","s":"Affrontare scenari più complessi senza perdere ridondanza, controllo e capacità di ritorno.","m":240,"p":true,"f":["deviazioni","risalita su fune","passaggio nodi/frazionamenti secondo tecnica","recuperabilità","stop"],"case":"Il percorso previsto diventa impraticabile per interferenza: scegliere rientro o configurazione alternativa prevista, senza improvvisare."},
    {"k":"rope:A:rescue","t":"Soccorso del compagno ed evacuazione su siti naturali/artificiali","s":"Eseguire le manovre di aiuto e recupero previste dall’addestramento con sicurezza del soccorritore.","m":240,"p":true,"f":["allarme","avvicinamento","trasferimento carico","discesa/evacuazione assistita","comunicazione","112/118"],"case":"Scenario con compagno incapace di proseguire: applicare la manovra addestrata e interrompere se la configurazione non è quella prevista."},
    {"k":"rope:B:tree-assessment","t":"Valutazione dell’albero, punto di accesso e installazione della linea","s":"Valutare struttura, ambiente e punti di installazione prima della salita.","m":240,"p":true,"f":["stabilità albero","difetti visibili","ramo/forcella","lancio/installazione linea","area sottostante","meteo"],"case":"L’albero presenta ramo secco vicino alla linea prevista: ridefinire accesso o sospendere finché lo scenario non è sicuro."},
    {"k":"rope:B:ascent","t":"Salita, discesa e movimento nella chioma","s":"Eseguire accesso e spostamenti nella chioma mantenendo sistemi e punti di lavoro coerenti.","m":240,"p":true,"f":["salita","discesa","movimento laterale","riposizionamento","gestione fune","protezione corteccia"],"case":"Raggiungere due postazioni nella chioma scegliendo transizioni che mantengano protezione continua."},
    {"k":"rope:B:positioning","t":"Posizionamento operativo e uso controllato degli attrezzi","s":"Gestire posizione, attrezzature e zone di caduta durante il lavoro arboricolo.","m":240,"p":true,"f":["posizionamento","seconda sicurezza quando prevista","attrezzi","zona di caduta","comunicazione a terra"],"case":"Simulare potatura con area sottostante segregata e attrezzi gestiti senza compromettere il sistema."},
    {"k":"rope:B:rigging-awareness","t":"Interferenze con taglio, movimentazione e carichi nella chioma","s":"Riconoscere come rami, corde di lavoro e materiali movimentati possono interferire con il sistema di accesso.","m":240,"p":true,"f":["taglio","caduta rami","corde di servizio","carichi","separazione sistemi","comunicazione"],"case":"Una corda di movimentazione attraversa la zona della linea operatore: riprogettare i percorsi delle corde prima del taglio."},
    {"k":"rope:B:rescue","t":"Soccorso e recupero del compagno su albero","s":"Applicare piano e tecniche di recupero addestrate senza creare un secondo infortunato.","m":240,"p":true,"f":["accesso soccorritore","trasferimento","discesa assistita","area a terra","comunicazione","EMS"],"case":"Operatore non risponde in chioma: attivare il piano, raggiungerlo con tecnica addestrata e preparare ricezione a terra."},
    {"k":"rope:upd:A:review","t":"Aggiornamento tecnico: attrezzature, procedure, eventi e pianificazione","s":"Riesaminare evoluzione di dispositivi, tecniche e criticità osservate nei lavori su siti naturali/artificiali.","m":240,"p":false,"f":["novità DPI","controlli","ancoraggi","protezione funi","procedure","near miss","soccorso"],"case":"Analizzare un near miss dovuto a protezione insufficiente su spigolo e ridefinire barriere."},
    {"k":"rope:upd:A:practice","t":"Aggiornamento pratico: progressione, configurazioni e soccorso","s":"Rinnovare capacità pratiche su manovre già apprese e gestione di una criticità.","m":240,"p":true,"f":["salita/discesa","frazionamenti","riposizionamento","controllo DPI","soccorso","evacuazione"],"case":"Percorso pratico con anomalia introdotta dal docente e manovra di aiuto al compagno."},
    {"k":"rope:upd:B:review","t":"Aggiornamento tecnico: albero, attrezzature, procedure ed eventi","s":"Riesaminare evoluzione di dispositivi, tecniche e criticità nei lavori arboricoli su fune.","m":240,"p":false,"f":["valutazione albero","novità DPI","punti installazione","interferenze","near miss","soccorso"],"case":"Analizzare un evento in cui una corda di lavoro interferisce con materiale movimentato e ridefinire l’organizzazione."},
    {"k":"rope:upd:B:practice","t":"Aggiornamento pratico: accesso, movimento in chioma e recupero","s":"Rinnovare capacità pratiche su salita, spostamento, posizionamento e soccorso.","m":240,"p":true,"f":["salita","discesa","movimento chioma","riposizionamento","controlli","recupero compagno"],"case":"Circuito pratico nella chioma/addestratore con variazione controllata e recupero simulato."},
    {"k":"rope:preposto:planning","t":"Programmazione e scelta del sistema di lavoro","s":"Valutare se squadra, attrezzature, accessi e piano di soccorso sono coerenti con il compito.","m":120,"p":false,"f":["programmazione","competenze squadra","attrezzature","ancoraggi","condizioni ambientali","rescue"],"case":"Il cliente modifica il punto di accesso il giorno del lavoro: il preposto decide se il piano resta applicabile."},
    {"k":"rope:preposto:briefing","t":"Briefing, assegnazione ruoli e sorveglianza","s":"Organizzare la squadra e verificare continuamente condizioni e comportamenti.","m":120,"p":false,"f":["briefing","ruoli","comunicazione","controllo reciproco","stop work","sorveglianza"],"case":"Un operatore esperto propone una scorciatoia non prevista: gestire rifiuto, comunicazione e ripristino."},
    {"k":"rope:preposto:change","t":"Gestione delle variazioni e delle condizioni di stop","s":"Riconoscere cambiamenti che richiedono sospensione e nuova pianificazione.","m":120,"p":true,"f":["meteo","ancoraggi","interferenze","guasti","fatica","visibilità","escalation"],"case":"A metà turno cambia il vento e una zona diventa difficilmente comunicabile: decidere stop e rivalutazione."},
    {"k":"rope:preposto:emergency","t":"Coordinamento dell’emergenza e giudizio di affidabilità","s":"Dirigere la prima risposta e verificare che il piano di soccorso sia realmente eseguibile.","m":120,"p":true,"f":["allarme","ruoli soccorso","recupero","accesso soccorsi","comunicazione","debriefing"],"case":"Simulazione: operatore in difficoltà; il preposto coordina squadra, soccorso previsto e passaggio ai professionisti."},
    {"k":"rope:preposto:update","t":"Aggiornamento sorveglianza: nuove tecniche, controllo e gestione emergenze","s":"Aggiornare capacità di programmazione, controllo e coordinamento della squadra su funi.","m":240,"p":true,"f":["nuove attrezzature","tecniche operative","near miss","briefing","stop","soccorso","affidabilità squadra"],"case":"Scenario integrato con modifica tecnica e operatore in difficoltà: rivalutare piano, fermare e coordinare il recupero."}
  ]::jsonb) LOOP
    v_practical := (r->>'p')::boolean;
    INSERT INTO public.learning_units(stable_key,title,summary,default_minutes,source_group,tags,active,metadata) VALUES(r->>'k',r->>'t',r->>'s',(r->>'m')::int,'SafetyTraining funi-v2',array['safetytraining','funi','allegato-xxi'],true,jsonb_build_object('learner_ready',true,'teacher_ready',true,'practical_focus',v_practical)) ON CONFLICT(stable_key) DO UPDATE SET title=excluded.title,summary=excluded.summary,default_minutes=excluded.default_minutes,source_group=excluded.source_group,tags=excluded.tags,active=true,metadata=excluded.metadata,updated_at=now() RETURNING id INTO v_lu;
    v_content := jsonb_build_object('case',r->>'case','norm','D.Lgs. 81/2008 art. 116 e Allegato XXI; istruzioni dei fabbricanti e procedure specifiche del sistema di accesso e posizionamento mediante funi.','quiz',jsonb_build_object('options',jsonb_build_array('Adattare la manovra sul momento','Continuare affidandosi all’esperienza','Fermarsi, mantenere una condizione protetta e rivalutare sistema/piano','Ridurre solo la velocità'),'question','Se ancoraggio, fune, comunicazione o piano di soccorso non corrispondono più allo scenario previsto, cosa si fa?','explanation','Nel lavoro su funi una variazione non prevista può compromettere ridondanza e recuperabilità: la risposta corretta è stop e rivalutazione.','correct_index',2),'focus',r->'f','title',r->>'t','detail','L’accesso e il posizionamento mediante funi richiedono pianificazione, ridondanza, compatibilità dei dispositivi e capacità di recupero. Ogni passaggio deve essere eseguibile con il sistema previsto e con un margine chiaro: se ancoraggio, fune, comunicazione, ambiente o piano di soccorso non corrispondono allo scenario, il lavoro si ferma. L’esperienza non autorizza configurazioni improvvisate.','minutes',(r->>'m')::int,'quality',jsonb_build_object('learner_ready',true,'teacher_ready',true,'scenario_based',true,'practical_focus',v_practical),'summary',r->>'s','visuals',jsonb_build_array('procedura-operativa-5-fasi.svg','stop-segnala-ripristina.svg','modello-farfalla-rischio.svg'),'procedure',case when v_practical then jsonb_build_array('controllare area, DPI, funi e ancoraggi','verbalizzare la sequenza prima di muoversi','eseguire la manovra mantenendo ridondanza e comunicazione','arrestarsi se il sistema non corrisponde alla configurazione prevista','chiudere con controllo, ripristino e debriefing') else jsonb_build_array('definire compito e ambiente','identificare pericoli, accesso e sistema di lavoro','verificare attrezzature, competenze e piano di soccorso','stabilire comunicazione e criteri di stop','riesaminare il piano quando cambia una condizione') end,'common_errors',jsonb_build_array('usare componenti solo perché fisicamente compatibili','proteggere il lavoratore ma non la fune da spigoli/interferenze','iniziare senza piano di recupero praticabile','continuare dopo perdita di comunicazione o variazione non prevista'),'delivery_note','Il materiale resta disponibile integralmente; le manovre e le prove di recupero richiedono addestramento effettivo in sito/palestra idonei e non sono sostituite dalla sola consultazione digitale.','guided_activity',jsonb_build_array('briefing dello scenario','controllo sistema e compatibilità','esecuzione o simulazione guidata','variazione controllata/condizione di stop','debriefing su tecnica, decisione e soccorso'),'didactic_version','funi-v2','final_assessment',false,'teacher_expansion',case when v_practical then 'Usare palestra/sito addestrativo idoneo, attrezzature coerenti con l’indirizzo e rapporto istruttore/discenti adeguato alle manovre. Ogni partecipante esegue personalmente. Inserire variazioni controllate senza creare esposizione reale e valutare tecnica, decisione, comunicazione e capacità di fermarsi.' else 'Usare schemi di installazione, DPI reali e casi. Far motivare la scelta del sistema e chiedere sempre: quale barriera impedisce la caduta? quale protegge la fune? come recuperiamo l’operatore?' end);
    INSERT INTO public.learning_unit_versions(learning_unit_id,version_number,status,content,published_at) VALUES(v_lu,1,'draft',v_content,null) ON CONFLICT(learning_unit_id,version_number) DO UPDATE SET status='draft',content=excluded.content,published_at=null;
    INSERT INTO public.learning_unit_sources(learning_unit_id,source_key,purpose,relevance_note,verified_on,metadata) VALUES(v_lu,'piemonte-indicazioni-formazione-2025','compliance_crosscheck','Cross-check operativo delle regole formative successive al recepimento ASR 2025.',date '2026-10-15','{}') ON CONFLICT(learning_unit_id,source_key,purpose) DO UPDATE SET relevance_note=excluded.relevance_note,verified_on=excluded.verified_on;
  END LOOP;

  FOR c IN SELECT value FROM jsonb_array_elements($courses$
  [
    {"k":"funi_siti_32h","t":"Accesso e posizionamento mediante funi – Siti naturali/artificiali – 32h","d":"Formazione teorico-pratica per lavoratori addetti ai sistemi di accesso e posizionamento mediante funi, indirizzo siti naturali o artificiali.","m":1920,"v":"funi-v2","bp":"funi_siti_32h","meta":{"direction":"A - siti naturali/artificiali","attendance_min_pct":90,"final_practical_test_required":true},"basis":"D.Lgs. 81/2008 art.116 e Allegato XXI"},
    {"k":"funi_alberi_32h","t":"Accesso e attività lavorativa su alberi mediante funi – 32h","d":"Formazione teorico-pratica per lavoratori addetti ai sistemi di accesso e posizionamento mediante funi, indirizzo attività lavorativa su alberi.","m":1920,"v":"funi-v2","bp":"funi_alberi_32h","meta":{"direction":"B - attività lavorativa su alberi","attendance_min_pct":90,"final_practical_test_required":true},"basis":"D.Lgs. 81/2008 art.116 e Allegato XXI"},
    {"k":"agg_funi_siti_8h","t":"Aggiornamento lavori su funi – Siti naturali/artificiali – 8h","d":"Aggiornamento quinquennale addetti funi indirizzo siti naturali/artificiali: minimo 8 ore di cui almeno 4 tecnico-pratiche.","m":480,"v":"funi-update-v2","bp":"agg_funi_siti_8h","meta":{"direction":"A","renewal_months":60,"technical_practical_min_minutes":240},"basis":"D.Lgs. 81/2008 Allegato XXI"},
    {"k":"agg_funi_alberi_8h","t":"Aggiornamento lavori su funi – Alberi – 8h","d":"Aggiornamento quinquennale addetti funi indirizzo attività lavorativa su alberi: minimo 8 ore di cui almeno 4 tecnico-pratiche.","m":480,"v":"funi-update-v2","bp":"agg_funi_alberi_8h","meta":{"direction":"B","renewal_months":60,"technical_practical_min_minutes":240},"basis":"D.Lgs. 81/2008 Allegato XXI"},
    {"k":"preposto_funi_8h","t":"Preposto con funzione di sorveglianza lavori su funi – 8h","d":"Modulo specifico per operatori già formati su funi destinati alla funzione di sorveglianza dei lavori.","m":480,"v":"funi-preposto-v2","bp":"preposto_funi_8h","meta":{"final_interview_required":true,"requires_prior_operator_course":true},"basis":"D.Lgs. 81/2008 art.116 e Allegato XXI"},
    {"k":"agg_preposto_funi_4h","t":"Aggiornamento preposto/sorvegliante lavori su funi – 4h","d":"Aggiornamento quinquennale della funzione specifica di sorveglianza dei lavori su funi.","m":240,"v":"funi-preposto-update-v2","bp":"agg_preposto_funi_4h","meta":{"renewal_months":60},"basis":"D.Lgs. 81/2008 Allegato XXI"}
  ]::jsonb) LOOP
    INSERT INTO public.courses(stable_key,title,family,description,nominal_minutes,certification_mode,active,metadata) VALUES(c->>'k',c->>'t','Lavori in quota specialistici',c->>'d',(c->>'m')::int,'internal_learning',true,jsonb_build_object('blueprint_key',c->>'bp','didactic_version',c->>'v','regulatory_basis',c->>'basis','material_complete',true,'requires_admin_review',true,'learner_catalog_hidden',true,'delivery_rules_are_metadata_only',true)||coalesce(c->'meta','{}'::jsonb)) ON CONFLICT(stable_key) DO UPDATE SET title=excluded.title,family=excluded.family,description=excluded.description,nominal_minutes=excluded.nominal_minutes,active=true,metadata=excluded.metadata,updated_at=now() RETURNING id INTO v_course;
    INSERT INTO public.course_versions(course_id,version_number,status,syllabus_snapshot,normative_snapshot,published_at) VALUES(v_course,1,'draft',jsonb_build_object('total_minutes',(c->>'m')::int,'didactic_version',c->>'v','material_complete',true),jsonb_build_object('basis',c->>'basis'),null) ON CONFLICT(course_id,version_number) DO UPDATE SET status='draft',syllabus_snapshot=excluded.syllabus_snapshot,normative_snapshot=excluded.normative_snapshot,published_at=null;
  END LOOP;

  FOR c IN SELECT value FROM jsonb_array_elements($modules$
  [
    {"c":"funi_siti_32h","mk":"rope-base","mt":"Modulo base teorico-pratico – 12h","mp":1,"mm":720,"u":[["rope:base:risk",1,false],["rope:base:equipment",2,true],["rope:base:anchors-rescue",3,true]]},{"c":"funi_siti_32h","mk":"rope-A","mt":"Modulo A specifico pratico – siti naturali/artificiali – 20h","mp":2,"mm":1200,"u":[["rope:A:setup",1,true],["rope:A:progression",2,true],["rope:A:positioning",3,true],["rope:A:complex",4,true],["rope:A:rescue",5,true]]},
    {"c":"funi_alberi_32h","mk":"rope-base","mt":"Modulo base teorico-pratico – 12h","mp":1,"mm":720,"u":[["rope:base:risk",1,false],["rope:base:equipment",2,true],["rope:base:anchors-rescue",3,true]]},{"c":"funi_alberi_32h","mk":"rope-B","mt":"Modulo B specifico pratico – attività lavorativa su alberi – 20h","mp":2,"mm":1200,"u":[["rope:B:tree-assessment",1,true],["rope:B:ascent",2,true],["rope:B:positioning",3,true],["rope:B:rigging-awareness",4,true],["rope:B:rescue",5,true]]},
    {"c":"agg_funi_siti_8h","mk":"rope-upd-A","mt":"Aggiornamento funi – siti – 8h","mp":1,"mm":480,"u":[["rope:upd:A:review",1,false],["rope:upd:A:practice",2,true]]},{"c":"agg_funi_alberi_8h","mk":"rope-upd-B","mt":"Aggiornamento funi – alberi – 8h","mp":1,"mm":480,"u":[["rope:upd:B:review",1,false],["rope:upd:B:practice",2,true]]},
    {"c":"preposto_funi_8h","mk":"rope-supervisor","mt":"Modulo specifico preposto funi – 8h","mp":1,"mm":480,"u":[["rope:preposto:planning",1,false],["rope:preposto:briefing",2,false],["rope:preposto:change",3,true],["rope:preposto:emergency",4,true]]},{"c":"agg_preposto_funi_4h","mk":"rope-supervisor-upd","mt":"Aggiornamento preposto funi – 4h","mp":1,"mm":240,"u":[["rope:preposto:update",1,true]]}
  ]::jsonb) LOOP
    SELECT cv.id INTO v_cv FROM public.course_versions cv JOIN public.courses co ON co.id=cv.course_id WHERE co.stable_key=c->>'c' AND cv.version_number=1;
    INSERT INTO public.course_modules(course_version_id,module_key,title,position,nominal_minutes) VALUES(v_cv,c->>'mk',c->>'mt',(c->>'mp')::int,(c->>'mm')::int) ON CONFLICT(course_version_id,module_key) DO UPDATE SET title=excluded.title,position=excluded.position,nominal_minutes=excluded.nominal_minutes RETURNING id INTO v_module;
    FOR r IN SELECT value FROM jsonb_array_elements(c->'u') LOOP SELECT luv.id INTO v_luv FROM public.learning_units lu JOIN public.learning_unit_versions luv ON luv.learning_unit_id=lu.id AND luv.version_number=1 WHERE lu.stable_key=r->>0; INSERT INTO public.course_module_units(module_id,unit_version_id,position,required,min_active_seconds,requires_comprehension,completion_rules) VALUES(v_module,v_luv,(r->>1)::int,true,0,true,jsonb_build_object('material_complete',true,'practical_or_guided',(r->>2)::boolean)) ON CONFLICT(module_id,unit_version_id) DO UPDATE SET position=excluded.position,required=true,min_active_seconds=0,requires_comprehension=true,completion_rules=excluded.completion_rules; END LOOP;
  END LOOP;
END $do$;
